CREATE TABLE "serving"."orders" ("order_id" BIGINT GENERATED BY DEFAULT AS IDENTITY(100, 10), "customer_id" INTEGER ENCODE AZ64 NOT NULL, "amount" NUMERIC(12,2) DEFAULT 0, "created_at" TIMESTAMP WITHOUT TIME ZONE DEFAULT getdate() ENCODE RAW NOT NULL, "note" CHARACTER VARYING(256) DEFAULT 'n/a' -- trailing comment
 ENCODE TEXT255, PRIMARY KEY ("order_id"), UNIQUE ("customer_id", "created_at"), UNIQUE ("note"), FOREIGN KEY ("customer_id") REFERENCES "crm"."customers" ("id")) BACKUP NO DISTSTYLE ALL INTERLEAVED SORTKEY ("created_at", "customer_id");
